"""The Sentinel action catalog (catalog/actions.csv), generated by scripts/build_catalog.py.

An action id is a workspace event's `catalog_action`: `<app>.<verb>[:tag...]`, e.g.
`jmail.send:known_contact`, `habspot.stage:stage_skip`, `quote.send:over_limit:not_approved`,
`jdrive.open:transcript:internal` (ADR 0007, docs/event-contract.md §4-5).

The CSV holds the BehaviorGPT columns plus our own: `irreversible`, `role` (workflow | benign |
wrong) and `phase` (research | act | any). `catalog_from_csv` drops the extra columns, so they never
reach Unbox. BehaviorGPT's `complete()` takes at most 100 results per call, so rank a larger
catalog in `id_chunks()` with `filters={"id": chunk}`.
"""

from __future__ import annotations

import csv
import re
from dataclasses import dataclass
from functools import cache
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CATALOG_CSV = ROOT / "catalog" / "actions.csv"

ID_RE = re.compile(
    r"^(jmail|jdrive|habspot|calendar|quote)\.[a-z]+(_[a-z]+)*(:[a-z0-9]+(_[a-z0-9]+)*)*$"
)
APP_OF_PREFIX = {
    "jmail": "Jmail",
    "jdrive": "Jdrive",
    "habspot": "Habspot",
    "calendar": "Calendario",
    "quote": "Quotes",
}
APP = APP_OF_PREFIX
ROLES = {"workflow", "benign", "wrong"}
PHASES = {"research", "act", "any"}
MAX_IDS_PER_CALL = 100  # BehaviorGPT complete(): limit <= 100, and one id filter holds <= 100


@dataclass(frozen=True)
class Action:
    id: str
    name: str
    app: str
    categories: str
    irreversible: bool
    role: str
    phase: str


def base_action(action_id: str) -> str:
    """`jmail.send:known_contact` -> `jmail.send` (the workspace event's raw `action`)."""
    return action_id.split(":", 1)[0]


def tags_of(action_id: str) -> list[str]:
    """`quote.send:over_limit:not_approved` -> `["over_limit", "not_approved"]`."""
    return action_id.split(":")[1:]


@cache
def load_catalog(path: Path = CATALOG_CSV) -> dict[str, Action]:
    with path.open(newline="") as f:
        rows = list(csv.DictReader(f))
    out: dict[str, Action] = {}
    for row in rows:
        a = Action(
            id=row["id"],
            name=row["name"],
            app=row["brand"],
            categories=row["categories"],
            irreversible=row["irreversible"] == "true",
            role=row["role"],
            phase=row["phase"],
        )
        if a.id in out:
            raise ValueError(f"duplicate action id {a.id}")
        out[a.id] = a
    return out


def id_chunks(size: int = MAX_IDS_PER_CALL) -> list[list[str]]:
    """Catalog ids in groups that each fit one BehaviorGPT ranking call."""
    ids = list(load_catalog())
    return [ids[i : i + size] for i in range(0, len(ids), size)]
